import{_ as e,a as o,b as r,c as i,d as a,e as l,f as n,g as s,h as c,i as h,j as d,k as p,l as m,m as u,n as f,o as g,p as _,q as b,r as v,s as w,t as x,u as C,v as y,w as k,x as S,y as T,z as P,A as q,B as A}from"./chunks/falcon_vertigo_55_level_motors.Zq22Rf3B.js";import{_ as F}from"./chunks/px4_frame_generic_standard_vtol.D8XeIu3k.js";import{_ as V,o as I,c as R,al as N,j as O}from"./chunks/framework.7vp1BMOE.js";const H=JSON.parse('{"title":"단종 : Falcon Vertigo Hybrid VTOL RTF (Dropix)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/frames_vtol/vtol_quadplane_falcon_vertigo_hybrid_rtf_dropix.md","filePath":"ko/frames_vtol/vtol_quadplane_falcon_vertigo_hybrid_rtf_dropix.md"}'),E={name:"ko/frames_vtol/vtol_quadplane_falcon_vertigo_hybrid_rtf_dropix.md"};function M(B,t,D,G,L,U){return I(),R("div",null,[...t[0]||(t[0]=[N('<h1 id="단종-falcon-vertigo-hybrid-vtol-rtf-dropix" tabindex="-1">단종 : Falcon Vertigo Hybrid VTOL RTF (Dropix) <a class="header-anchor" href="#단종-falcon-vertigo-hybrid-vtol-rtf-dropix" aria-label="Permalink to &quot;단종 : Falcon Vertigo Hybrid VTOL RTF (Dropix)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Discontinued The Falcon Venturi FPV Wing frame on which this vehicle is based is no longer available. The Dropix FC used by this vehicle is discontinued.</p></div><p>The <em>Falcon Vertigo Hybrid VTOL</em> is a quadplane VTOL aircraft that has been designed to work with PX4 and the Dropix (Pixhawk compatible) flight controller. 소형 GoPro 카메라를 장착할 수 있습니다.</p><p>RTF 키트에는 RC 수신기와 텔레메트리를 제외하고, 시스템에 필요한 부품들이 포함되어 있습니다. 부품들을 별도로 구매할 수 있습니다.</p><p>주요 정보:</p><ul><li><strong>Frame:</strong> Falcon Vertigo Hybrid VTOL</li><li><strong>Flight controller:</strong> Dropix (Discontineud)</li><li><strong>Wing span:</strong> 1.3m</li></ul><p><img src="'+e+'" alt="Falcon Vertigo Hybrid VTOL RTF"></p><h2 id="부품-명세서" tabindex="-1">부품 명세서 <a class="header-anchor" href="#부품-명세서" aria-label="Permalink to &quot;부품 명세서&quot;">​</a></h2><p>필요한 대부분의 부품들이 RTF 키트에 포함되어 있습니다. 부품을 별도 구매하는 경우에는, 아래 부품 목록의 링크를 참고하십시오.</p><ul><li>사전 적층 EPP 날개</li><li>윙팁 및 전체 하드웨어</li><li>Dropix flight controller (discontinued) with <ul><li>GPS u-blox M8N</li><li>전원 센서:</li><li><a href="https://store-drotek.com/793-digital-differential-airspeed-sensor-kit-.html" target="_blank" rel="noreferrer">Airspeed Sensor</a></li></ul></li><li>Quad power set <a href="https://www.getfpv.com/tiger-motor-mt-2216-11-900kv-v2.html" target="_blank" rel="noreferrer">Tiger Motor MT-2216-11 900kv V2</a> (discontinued)</li><li>4 x 프로펠러 10”x 5”(쿼드 모터)</li><li>4 x <a href="https://www.getfpv.com/tiger-motor-flame-25a-esc.html" target="_blank" rel="noreferrer">ESC 25A</a></li><li>프로펠러 10”x 5”1 개 (푸셔 모터)</li><li>1 x ESC 30A</li><li>푸셔 모터 전원 시스템</li><li>탄소 섬유 튜브 및 마운트</li><li>G10 모터 마운트</li><li>1 x <a href="https://wheelspinmodels.co.uk/i/3700mah-4s-14.8v-25c-lipo-battery-overlander-262221/" target="_blank" rel="noreferrer">3700mah 4S 30C Lipo battery</a></li><li>Dropix power distribution board and cable</li></ul><p>이 키트는 라디오 수신기 또는 텔레메트리(선택 사항)는 제공하지 않습니다. 다음의 부품을 사용하여 조립하였습니다.</p><ul><li>Receiver: <a href="https://www.frsky-rc.com/product/d4r-ii/" target="_blank" rel="noreferrer">FrSSKY D4R-II</a></li><li>Telemetry: <a href="https://www.getfpv.com/holybro-100mw-fpv-transceiver-telemetry-radio-set-915mhz.html" target="_blank" rel="noreferrer">Holybro 100mW 915MHz modules</a> (Discontinued)</li></ul><h2 id="필요한-공구들" tabindex="-1">필요한 공구들 <a class="header-anchor" href="#필요한-공구들" aria-label="Permalink to &quot;필요한 공구들&quot;">​</a></h2><p>아래의 도구들을 사용하여 기체를 조립하였습니다.</p><ul><li>필립스 스크류드라이버</li><li>5.5 mm 육각 스크류드라이버</li><li>전선 커터</li><li>납땜 인두 및 땜납</li><li>취미 스테인리스 핀셋</li><li>고릴라 접착제</li><li>유리 섬유 강화 테이프</li></ul><p><img src="'+o+'" alt="Build tools"></p><h2 id="조립-단계" tabindex="-1">조립 단계 <a class="header-anchor" href="#조립-단계" aria-label="Permalink to &quot;조립 단계&quot;">​</a></h2><p>RTF 키트는 아래와 같이 조립하여야 합니다.</p><h3 id="_1-단계-모터-마운트-부착" tabindex="-1">1 단계 : 모터 마운트 부착 <a class="header-anchor" href="#_1-단계-모터-마운트-부착" aria-label="Permalink to &quot;1 단계 : 모터 마운트 부착&quot;">​</a></h3><ol><li><p>그림과 같이 윙 브래킷 내부에 고릴라 접착제를 펴서 바릅니다.</p><p><img src="'+r+'" alt="Add glue on wing brackets"></p></li><li><p>브래킷에 카본 튜브를 부착합니다. 브래킷과 튜브는 흰색 표시를 사용하여 정렬합니다 (그림 참조).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This is very important because the white mark indicates the center of gravity.</p></div></li></ol><p>:::</p><img src="'+i+'" title="Carbon tube in brackets" width="300px"><ol start="3"><li><p>다음 이미지는 다른 관점에서 막대들의 정렬을 보여줍니다.</p><p><img src="'+a+'" alt="quad motor frame rod alignment from bottom"><img src="'+l+'" alt="quad motor frame rod alignment schematic"></p></li></ol><h3 id="_2-단계-날개-부착" tabindex="-1">2 단계 : 날개 부착 <a class="header-anchor" href="#_2-단계-날개-부착" aria-label="Permalink to &quot;2 단계 : 날개 부착&quot;">​</a></h3><ol><li><p>두 탄소 튜브를 동체에 삽입합니다.</p><img src="'+n+'" width="500px" title="Fuselage carbon tubes"></li><li><p>각 튜브에있는 두 개의 흰색 표시 사이에 고릴라 접착제를 바릅니다 (빨간색 화살표로 표시됨). 중앙의 흰색 표시 (파란색 화살표)는 동체 중앙에 배치되고, 다른 표시는 측면에 배치됩니다.</p><img src="'+s+'" width="500px" title="Apply glue to rod"></li><li><p>탄소 튜브가 동체 내부에 있으면, 튜브의 나머지 부분에 고릴라 접착제를 바르고 날개를 부착하십시오.</p></li><li><p>동체에는 모터와 서보 케이블을 위한 두 개의 구멍이 있습니다. 구멍으로 케이블을 통과시킨 다음 날개를 동체에 연결합니다.</p><img src="'+c+'" width="500px" title="Fuselage holes for cables"></li><li><p>동체 내에 제공된 커넥터를 사용하여 방금 날개에서 ESC로 통과한 신호 케이블을 연결합니다. ESC는 이미 모터에 연결되어 있으며, 올바른 순서로 회전하도록 설정되어 있습니다 (나중 단계에서 ESC PDB를 전원 모듈에 연결해야 함).</p><img src="'+h+'" width="500px" title="Connect ESC power and signal cables"></li><li><p>ESC와 마찬가지로 서보는 이미 설치되어 있습니다. 날개 (동체를 통과)에서 비행 컨트롤러로 신호 케이블을 연결합니다.</p><img src="'+d+'" width="500px" title="Connect servo cables"></li><li><p>다른 날개에 이 단계를 반복합니다.</p></li></ol><h3 id="_3-단계-전자-장치-연결" tabindex="-1">3 단계 : 전자 장치 연결 <a class="header-anchor" href="#_3-단계-전자-장치-연결" aria-label="Permalink to &quot;3 단계 : 전자 장치 연결&quot;">​</a></h3><p>이 키트에는 필요한 전자 장치가 대부분 미리 연결된 Dropix 비행 컨트롤러가 포함되어 있습니다 (다른 Pixhawk 호환 비행 컨트롤러를 사용하는 경우 연결이 유사함).</p><img src="'+p+'" width="500px" title="Falcon Vertigo Electronics"><h4 id="connect-the-esc-power-connector-and-pass-the-signals-cables-to-the-flight-controller" tabindex="-1">Connect the ESC power connector and pass the signals cables to the flight controller <a class="header-anchor" href="#connect-the-esc-power-connector-and-pass-the-signals-cables-to-the-flight-controller" aria-label="Permalink to &quot;Connect the ESC power connector and pass the signals cables to the flight controller&quot;">​</a></h4><ol><li><p>Connect the ESC to the power module using the XT60 connector</p><img src="'+m+'" width="500px" title=""></li><li><p>Pass the signals cables through to the flight controller</p><img src="'+u+'" width="500px" title="GPS, ESC, Servo connections"></li></ol><h4 id="motor-wiring" tabindex="-1">Motor Wiring <a class="header-anchor" href="#motor-wiring" aria-label="Permalink to &quot;Motor Wiring&quot;">​</a></h4><p>Motor and servo wiring is nearly entirely up to you, but should match the <a href="./../airframes/airframe_reference#vtol_standard_vtol_generic_standard_vtol">Generic Standard VTOL</a> configuration, as shown in the airframe reference. The geometry and output assignment can be configured in the <a href="./../config/actuators#actuator-outputs">Actuators Configuration</a></p><p>For example, you might wire it up like this example (orientation as if &quot;sitting in the plane&quot;):</p><table tabindex="0"><thead><tr><th>포트</th><th>연결</th></tr></thead><tbody><tr><td>MAIN 1</td><td>Front right motor, CCW</td></tr><tr><td>MAIN 2</td><td>Back left motor, CCW</td></tr><tr><td>MAIN 3</td><td>Front left motor, CW</td></tr><tr><td>MAIN 4</td><td>Back right motor, CW</td></tr><tr><td>AUX 1</td><td>Left aileron</td></tr><tr><td>AUX 2</td><td>Right aileron</td></tr><tr><td>AUX 3</td><td>Elevator</td></tr><tr><td>AUX 4</td><td>Rudder</td></tr><tr><td>AUX 5</td><td>Throttle</td></tr></tbody></table><p><a id="dropix_back"></a></p><h4 id="flight-controller-connections-motors-servos-rc-receiver-current-sensor" tabindex="-1">Flight Controller Connections: Motors, Servos, RC receiver, current sensor <a class="header-anchor" href="#flight-controller-connections-motors-servos-rc-receiver-current-sensor" aria-label="Permalink to &quot;Flight Controller Connections: Motors, Servos, RC receiver, current sensor&quot;">​</a></h4><p>The image below shows back of the dropix flight controller, highlighting the outputs pins to connect quad motors cables, aileron signal cables, throttle motor, and the current sensor and receiver (RC IN) input pins.</p><img id="dropix_outputs" src="'+f+'" width="500px" title="Dropix motor/servo outputs"><ol><li><p>Connect quad motors signal cables.</p></li><li><p>Connect the aileron cables and throttle motor in the auxiliary outputs.</p></li><li><p>Connect the throttle motor signal cable from the ESC to the appropriate flight controller auxiliary port. Connect the ESC to the throttle motor.</p><img src="'+g+'" width="500px" title="Connect throttle motor"></li><li><p>Connect the receiver (RC IN).</p></li></ol><p><a id="dropix_front"></a></p><h4 id="flight-controller-connections-telemetry-airspeed-sensor-gps-buzzer-and-safety-switch" tabindex="-1">Flight Controller Connections: Telemetry, Airspeed Sensor, GPS, Buzzer and Safety Switch <a class="header-anchor" href="#flight-controller-connections-telemetry-airspeed-sensor-gps-buzzer-and-safety-switch" aria-label="Permalink to &quot;Flight Controller Connections: Telemetry, Airspeed Sensor, GPS, Buzzer and Safety Switch&quot;">​</a></h4><p>The sensor inputs, telemetry, buzzer and safety switch are located in the front of the flight controller, as shown in the connection diagram below.</p><img src="'+_+'" width="500px" alt="Dropix connectors front" title="Dropix connectors front"><ol><li><p>Connect the telemetry, airspeed sensor, GPS, buzzer and safety switch as shown.</p><img src="'+b+'" width="500px" title="Connect sensors"></li></ol><h4 id="flight-controller-connect-power-module-and-external-usb" tabindex="-1">Flight Controller: Connect power module and external USB <a class="header-anchor" href="#flight-controller-connect-power-module-and-external-usb" aria-label="Permalink to &quot;Flight Controller: Connect power module and external USB&quot;">​</a></h4><p>The inputs for the USB port, power module and external USB are located on the right side of the flight controller.</p><ol><li><p>Connect power and USB as shown</p><img src="'+v+'" width="500px" title="Connect power module and USB"></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The external USB is optional. It should be used if access to the USB port is difficult once the flight controller is mounted.</p></div><h4 id="install-the-pitot-tube-airspeed-sensor" tabindex="-1">Install the pitot tube (airspeed sensor) <a class="header-anchor" href="#install-the-pitot-tube-airspeed-sensor" aria-label="Permalink to &quot;Install the pitot tube (airspeed sensor)&quot;">​</a></h4><p>The pitot tube is installed on the front of the plane and connected to the airspeed sensor via a tube.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>It is important that nothing obstructs airflow to the Pitot tube. This is critical for fixed-wing flight and for transitioning from quad to plane.</p></div><ol><li><p>Install the Pitot tube in the front of the plane</p><img src="'+w+'" width="500px" title="Airspeed sensor mounting"></li><li><p>Secure the connecting tubing and ensure that it is not bent/kinked.</p><img src="'+x+'" width="500px" title="Airspeed sensor mounting"></li><li><p>Connect the tubes to the airspeed sensor.</p><img src="'+C+'" width="500px" title="Connect airspeed sensor and tubing"></li></ol><h4 id="install-connect-receiver-and-telemetry-module" tabindex="-1">Install/connect receiver and telemetry module <a class="header-anchor" href="#install-connect-receiver-and-telemetry-module" aria-label="Permalink to &quot;Install/connect receiver and telemetry module&quot;">​</a></h4><ol><li><p>Paste the receiver and telemetry module to the outside of the vehicle frame.</p><img src="'+y+'" width="500px" title="Paste receiver"></li><li><p>Connect the receiver to the RC IN port on the <em>back</em> of the dropix, as shown above (also see the <a href="#dropix_back">flight controller instructions</a>).</p></li><li><p>Connect the telemetry module to the <em>front</em> of the flight controller as shown below (see the <a href="#dropix_front">flight controller instructions</a> for more detail on the pins).</p><img src="'+k+'" width="500px" title="Paste telemetry module"></li></ol><p><a id="compass_gps"></a></p><h4 id="gps-compass-module" tabindex="-1">GPS/Compass module <a class="header-anchor" href="#gps-compass-module" aria-label="Permalink to &quot;GPS/Compass module&quot;">​</a></h4><p>The GPS/Compass module is already mounted on the wing, in the default orientation. You don&#39;t need to have to do anything extra for this!</p><img src="'+S+'" width="500px" title="GPS/Compass"><p><a id="flight_controller_orientation"></a></p><h4 id="mount-and-orient-the-flight-controller" tabindex="-1">Mount and orient the flight controller <a class="header-anchor" href="#mount-and-orient-the-flight-controller" aria-label="Permalink to &quot;Mount and orient the flight controller&quot;">​</a></h4><ol><li><p>Set your flight controller orientation to 270 degrees.</p><img src="'+T+'" width="500px" title="Flight controller orientation"></li><li><p>Secure the controller in place using vibration damping foam.</p></li></ol><h3 id="step-4-final-assembly-checks" tabindex="-1">Step 4: Final Assembly Checks <a class="header-anchor" href="#step-4-final-assembly-checks" aria-label="Permalink to &quot;Step 4: Final Assembly Checks&quot;">​</a></h3><p>The final assembly step is to check the vehicle is stable and that the motors have been set up correctly.</p><ol><li><p>Check that the motors turn in the correct directions (as in the QuadX diagram below).</p><img src="'+P+'" width="200px" title="Quad motor order/directions"><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If necessary the servo direction can be reversed using the <code>Rev Range (for servos)</code> checkbox associated with each servo output in the QGroundControl <a href="./../config/actuators#actuator-outputs">Actuator Output</a> configuration (for servos only) (this sets the <a href="./../advanced_config/parameter_reference#PWM_AUX_REV">PWM_AUX_REV</a> or <a href="./../advanced_config/parameter_reference#PWM_MAIN_REV">PWM_AUX_MAIN</a> parameter).</p></div></li></ol><p>:::</p><ol start="2"><li>Check the vehicle is balanced around the expected centre of gravity <ul><li><p>Hold the vehicle with your fingers at the center of gravity and check that the vehicle remains stable.</p><p><img src="'+q+'" alt="Level Centre of Gravity"></p></li><li><p>If the vehicle leans forward or backwards, move the motors to balance it.</p><p><img src="'+A+'" alt="Level Motors"></p></li></ul></li></ol><h2 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h2><p>Perform the normal <a href="./../config/">Basic Configuration</a>.</p><p>Notes:</p><ol><li><p>For <a href="./../config/airframe">Airframe</a> select the vehicle group/type as <em>Standard VTOL</em> and the specific vehicle as <a href="./../airframes/airframe_reference#vtol_standard_vtol_generic_standard_vtol">Generic Standard VTOL</a> as shown below.</p><p><img src="'+F+'" alt="QCG - Select Generic Standard VTOL"></p></li><li><p>Set the <a href="./../config/flight_controller_orientation">Autopilot Orientation</a> to <code>ROTATION_YAW_270</code> as the autopilot is mounted <a href="#flight_controller_orientation">sideways</a> with respect to the front of the vehicle. The compass is oriented forward, so you can leave that at the default (<code>ROTATION_NONE</code>).</p></li><li><p>Configure the outputs and geometry following the instructions in <a href="./../config/actuators">Actuators Configuration</a></p></li><li><p>The default parameters are often sufficient for stable flight. For more detailed tuning information see <a href="./../config_vtol/vtol_quad_configuration">Standard VTOL Wiring and Configuration</a>.</p></li></ol><p>After you finish calibration the VTOL is ready to fly.</p><h2 id="비디오" tabindex="-1">비디오 <a class="header-anchor" href="#비디오" aria-label="Permalink to &quot;비디오&quot;">​</a></h2>',72),O("lite-youtube",{videoid:"h7OHTigtU0s",title:"PX4 Vtol test"},null,-1)])])}const Q=V(E,[["render",M]]);export{H as __pageData,Q as default};
